js='''
const slides=[...document.querySelectorAll('.slide')],toc=document.querySelector('#toc');let current=0;
slides.forEach((s,i)=>{const o=document.createElement('option');o.value=i;o.textContent=`${i+1}. ${s.querySelector('h1,h2').textContent}`;toc.append(o)});
function show(n,scroll=true){current=Math.max(0,Math.min(slides.length-1,n));slides.forEach((s,i)=>{s.classList.toggle('active',i===current);s.setAttribute('aria-hidden',i!==current)});document.querySelector('#counter').textContent=`${current+1} / ${slides.length}`;document.querySelector('#prev').disabled=current===0;document.querySelector('#next').disabled=current===slides.length-1;toc.value=current;document.querySelector('#progress').style.width=`${(current+1)/slides.length*100}%`;history.replaceState(null,'',`#${current+1}`);if(scroll)window.scrollTo(0,0)}
document.querySelector('#prev').onclick=()=>show(current-1);document.querySelector('#next').onclick=()=>show(current+1);toc.onchange=()=>show(Number(toc.value));
document.addEventListener('keydown',e=>{if(e.target.closest('button,select,input,textarea,summary,a'))return;if(['ArrowRight','PageDown'].includes(e.key)){e.preventDefault();show(current+1)}if(['ArrowLeft','PageUp'].includes(e.key)){e.preventDefault();show(current-1)}if(e.key==='Home')show(0);if(e.key==='End')show(slides.length-1)});
show(Number(location.hash.slice(1))-1||0,false);
const left=document.querySelector('#left'),right=document.querySelector('#right'),result=document.querySelector('#result'),hist=document.querySelector('#history');let attempts=[],hints=0;
function isOpen(a,b){return a===b}
document.querySelector('#test-pair').onclick=()=>{const a=left.value,b=right.value,open=isOpen(a,b);const txt=`${a} ${b} → ${open?'開門 ✓':'關門 ×'}`;result.textContent=txt;attempts.push(txt);hist.replaceChildren(...attempts.map(t=>{const li=document.createElement('li');li.textContent=t;return li}));hist.scrollTop=hist.scrollHeight};
document.querySelector('#hint').onclick=()=>{hints=Math.min(2,hints+1);document.querySelector('#hint-text').textContent=hints===1?'比較相同與不同的配對。△ △ 能幫你排除「只能用圓形」嗎？':'本例規則：兩個符號相同就開門。用新符號測試你是否理解了關係。';document.querySelector('#hint').textContent=hints===1?'提示 2 / 2':'提示已全部開啟';document.querySelector('#hint').disabled=hints===2};
document.querySelectorAll('[data-pair]').forEach(b=>b.onclick=()=>{document.querySelector('#transfer-result').textContent=b.dataset.pair==='◇◇'?'正確：符號換了，相同的關係仍成立。':'門仍關著：這兩個符號不同。可以再試一次。'});
document.querySelector('#reset').onclick=()=>{left.selectedIndex=right.selectedIndex=0;attempts=[];hints=0;result.textContent='你預測門會開還是關？';hist.innerHTML='<li>還沒有新試驗。</li>';document.querySelector('#hint-text').textContent='提示由你決定何時開啟。';document.querySelector('#hint').textContent='提示 1 / 2';document.querySelector('#hint').disabled=false;document.querySelector('#transfer-result').textContent='找到規則後再作答。'};
document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-answer]').forEach(x=>x.classList.remove('correct'));if(b.dataset.answer==='right')b.classList.add('correct');document.querySelector('#quiz-feedback').textContent=b.dataset.answer==='right'?'B 較合適：這個情境的目標是讓玩家提出並修正假設。可比較的結果讓推理有依據。':'再想一想：目前缺少的是可說明的假設。先補足觀察與回饋，才能知道他卡在哪裡。'});
'''
