def shell(title,body,script=''):
 return f'<!doctype html><html lang="zh-Hant"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{E(title)}</title><link rel="stylesheet" href="style.css"></head><body>{body}{script}</body></html>'
