# Small dependency-free Markdown renderer for this repository's deliberately simple documents.
def inline(t,current):
 t=E(t)
 def link(m):
  label,url=m.group(1),html.unescape(m.group(2))
  if not url.startswith(('http:','https:','#')):
   resolved=posixpath.normpath(posixpath.join(posixpath.dirname(current),url))
   url='wiki.html#'+anchor(resolved) if resolved.endswith('.md') else resolved
  return f'<a href="{E(url,quote=True)}">{label}</a>'
 t=re.sub(r'\[([^\]]+)\]\(([^)]+)\)',link,t)
 t=re.sub(r'`([^`]+)`',r'<code>\1</code>',t)
 return t

def md(text,current):
 out=[];code=[];in_code=False;table=False;ul=False
 def close():
  nonlocal table,ul
  if table:out.append('</table>');table=False
  if ul:out.append('</ul>');ul=False
 for line in text.splitlines():
  if line.startswith('```'):
   close()
   if in_code:out.append('<pre>'+E('\n'.join(code))+'</pre>');code=[]
   in_code=not in_code;continue
  if in_code:code.append(line);continue
  if line.startswith('|'):
   if re.fullmatch(r'[| :\-]+',line):continue
   if not table:close();out.append('<table>');table=True
   out.append('<tr>'+''.join('<td>'+inline(c.strip(),current)+'</td>' for c in line.strip('|').split('|'))+'</tr>');continue
  if line.startswith(('- ','1. ','2. ','3. ','4. ','5. ')):
   if not ul:close();out.append('<ul>');ul=True
   out.append('<li>'+inline(re.sub(r'^(?:- |\d+\. )','',line),current)+'</li>');continue
  close()
  if line.startswith('#'):
   n=len(line)-len(line.lstrip('#'));n=min(n+1,4)
   out.append(f'<h{n}>'+inline(line.lstrip('# ').strip(),current)+f'</h{n}>')
  elif line.startswith('> '):out.append('<blockquote>'+inline(line[2:],current)+'</blockquote>')
  elif line.strip():out.append('<p>'+inline(line,current)+'</p>')
 close();return '\n'.join(out)
